<?php
namespace App\Domain\ApiHub\Models;use App\Domain\Network\Tenancy\Models\Tenant;use App\Models\User;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Str;
final class TenantApiClient extends Model{public const STATUSES=['ACTIVE','SUSPENDED','REVOKED'];protected $fillable=['tenant_id','name','description','environment','status','created_by_user_id','last_used_at'];protected $casts=['last_used_at'=>'datetime'];protected static function booted():void{self::creating(fn(self$m)=>$m->uuid??=(string)Str::uuid());}public function tenant(){return$this->belongsTo(Tenant::class);}public function creator(){return$this->belongsTo(User::class,'created_by_user_id');}public function keys(){return$this->hasMany(TenantApiKey::class,'api_client_id');}public function webhooks(){return$this->hasMany(TenantApiWebhookEndpoint::class,'api_client_id');}}
